// ARM SysTick period interrupts
// Input: interrupts every 12.5ns*period
//        priority is 0 (highest) to 3 (lowest)
void Sound_Init(uint32_t period, uint32_t priority){
  SysTick->CTRL = 0;            // disable flag
  SysTick->LOAD = period - 1;
  SysTick->VAL  = 0;            // reset systick
  NVIC_SetPriority(SysTick_IRQn, priority);
}
void Sound_Stop(void){
  // either set LOAD to 0 or clear bit 1 in CTRL
  SysTick->LOAD = 0;
}


void Sound_Start(uint32_t period){
    i = 0;
    // set reload value
    // write any value to VAL, cause reload
    // write this
    SysTick->LOAD = period - 1;
    SysTick->VAL  = 0;
    SysTick->CTRL = 0x07; // En systick + 80mhz clk
}

// Interrupt service routine
// Executed every 12.5ns*(period)
void SysTick_Handler(void){
    // output one value to DAC
    if(fx == 0) {
      DAC5_Out(SinWave[i]);
    } else if(fx_num == 0) {
      DAC5_Out(explosion[i]);
    } else if(fx_num == 1) {
      DAC5_Out(ufo_lowpitch[i]);
    } else if(fx_num == 2) {
      DAC5_Out(slimeball[i]);
    } else if(fx_num == 3) {
      DAC5_Out(flaunch[i]);
    }
    i += 1;
    if(fx == 0 & i == 32) i = 0;
    else if(i == explosion_length & fx_num == 0) i = 0;
    else if(i == ufo_lowpitch_length & fx_num == 1) i = 0;
    else if(i == slimeball_length & fx_num == 2) i = 0;
    else if(i==flaunch_length & fx_num == 3) i = 0;
}

